# redraw chart from these counts
font = ImageFont.truetype(r"C:\Windows\Fonts\malgun.ttf", 15)
items = [(r["feature"], int(r["corpus_level12_unique_posts"])) for r in summary_rows]
items.sort(key=lambda x: -x[1])
row_h = 30
h = 80 + row_h * len(items)
chart = Image.new("RGB", (860, h), (255, 255, 255))
d = ImageDraw.Draw(chart)
d.text((16, 10), "기존 5,000건 중 수준 1·2 고유 게시물. 인기 순위가 아니다.", fill=(20, 20, 20), font=font)
d.text((16, 36), "분모 5,000. 막대는 긍정과 부정을 함께 센다. 한 글이 여러 막대에 들어갈 수 있다.", fill=(60, 60, 60), font=font)
max_n = max(n for _, n in items)
for i, (label, n) in enumerate(items):
    y = 68 + i * row_h
    d.text((16, y), label, fill=(20, 20, 20), font=font)
    bw = int(420 * n / max_n) if max_n else 0
    d.rectangle((180, y + 2, 180 + max(bw, 2), y + 20), fill=(70, 110, 160))
    d.text((190 + bw, y), f"{n} / 5000", fill=(20, 20, 20), font=font)
chart.save(base / "visuals" / "03_core_mention_counts.png")

